"""Exact Tie-Ceiling Evaluation for the Capped Trailing-Zero Dial.

Computes, in exact rational arithmetic, the largest squared Spearman rank
correlation attainable by T_u(x) = min(v2(x), u) on the key space
{0, ..., 2^b - 1}, by two independent routes, and certifies their agreement.

Route 1 (combinatorial):  build the tie profile and evaluate
                          rho^2 = 1 - sum_i (m_i^3 - m_i) / (N^3 - N).
Route 2 (closed form):    rho^2 = (6/7)(1 - 8^-u) * (1 + 1/(4^b - 1)).
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Sequence, Tuple


def cap_blocks(u: int, b: int) -> List[int]:
    """Tie-class sizes of T_u on b-bit keys; they sum to 2**b."""
    if not (1 <= u <= b):
        raise ValueError("require 1 <= u <= b")
    return [2 ** (b - 1 - j) for j in range(u)] + [2 ** (b - u)]


def tie_correction(profile: Sequence[int]) -> Fraction:
    """Spearman tie correction tc(L) = sum_i (m_i^3 - m_i) / 12."""
    return Fraction(sum(m ** 3 - m for m in profile), 12)


def ceiling_from_profile(profile: Sequence[int]) -> Fraction:
    """Exact tie ceiling of an arbitrary profile of tie-class sizes."""
    n = sum(profile)
    if n < 2:
        raise ValueError("need at least two items")
    return 1 - Fraction(12 * tie_correction(profile), n ** 3 - n)


def ceiling_closed_form(b: int, u: int) -> Fraction:
    """Closed product law: cap factor times bit factor."""
    return Fraction(6, 7) * (1 - Fraction(1, 8 ** u)) * (1 + Fraction(1, 4 ** b - 1))


def evaluate_ceiling(b: int, u: int) -> Tuple[Fraction, Fraction, bool]:
    """Return (combinatorial value, closed-form value, agreement flag)."""
    direct = ceiling_from_profile(cap_blocks(u, b))
    closed = ceiling_closed_form(b, u)
    return direct, closed, direct == closed


def cap_notch(b: int, u: int) -> Fraction:
    """Exact gain of the ceiling when the cap advances one notch:
    (3/4) * 8^-u * (1 + 1/(4^b - 1)) > 0."""
    return Fraction(3, 4) * Fraction(1, 8 ** u) * (1 + Fraction(1, 4 ** b - 1))


if __name__ == "__main__":
    for b, u in [(8, 3), (32, 8), (54, 10), (64, 12)]:
        direct, closed, ok = evaluate_ceiling(b, u)
        print(f"b={b:>3} u={u:>3}  rho^2 = {float(closed):.15f}  routes agree: {ok}"
              f"  cap notch = {float(cap_notch(b, u)):.3e} (> 0)")
